update public.learning_paths
set
  title = 'World History II',
  goal = 'World History II',
  summary = 'This foundational undergraduate History course surveys the modern world from roughly 1400 to the present. It emphasizes strong source work, regional balance, environmental history, gender and migration, decolonization, Cold War global history, public memory, data literacy, and a final research capstone.',
  data = $wh2json${"slug": "world-history-ii", "title": "World History II", "description": "This foundational undergraduate History course surveys the modern world from roughly 1400 to the present. It emphasizes strong source work, regional balance, environmental history, gender and migration, decolonization, Cold War global history, public memory, data literacy, and a final research capstone.", "topics": [{"id": "85d05857-8ccd-421e-a3ab-99535b93fba3", "type": "topic", "title": "World History II as a Field: Sources, Scale, and Modern Global Processes", "description": "Students learn how historians study the modern world at multiple scales, using comparison, connection, primary sources, data, and historiography without reducing global history to a single storyline.", "children": [{"id": "0c2d7847-4582-4a6a-b3a7-bcc29233f785", "type": "subtopic", "title": "Modern world history questions", "children": [{"id": "2e0a1581-b875-4322-83ef-5f9c65b4209a", "type": "concept", "title": "Comparison, connection, causation, contingency, periodization, and scale"}, {"id": "c58b1e9d-afd7-4b34-82f6-eaaaf3f91eb9", "type": "concept", "title": "Modernity, capitalism, empire, revolution, industrialization, nationalism, war, development, and globalization"}, {"id": "68872b17-f63a-4b25-b8e3-750c54212921", "type": "concept", "title": "Avoiding Eurocentrism, technological determinism, national tunnel vision, and single-cause narratives"}], "description": "Students learn how to frame questions that connect local lives to global systems."}, {"id": "94cdc838-8b63-4d4f-8588-0035c8f11863", "type": "subtopic", "title": "Sources, archives, and evidence", "children": [{"id": "0c333ba3-ab2d-4014-87dd-83bed5b5c9be", "type": "concept", "title": "Primary and secondary sources, archives, newspapers, statistics, oral histories, photographs, maps, and material culture"}, {"id": "e5d6c84f-97f0-445a-88ae-535a6c17b5fb", "type": "concept", "title": "Provenance, bias, silence, translation, genre, censorship, and archival power"}, {"id": "1991dd50-5fed-4499-ad83-994544827e00", "type": "concept", "title": "Sourcing, contextualization, corroboration, close reading, and citation"}], "description": "The point is to understand how historians reconstruct the modern world from uneven evidence."}, {"id": "0dc67379-5af3-4d41-8967-b7e6742ea3a6", "type": "subtopic", "title": "Global processes and historical argument", "children": [{"id": "c18a9113-c447-4e3c-b9fc-fb5a84a69daf", "type": "concept", "title": "Networks, states, empires, markets, migrations, technologies, social movements, and environments"}, {"id": "b03dc59b-16c5-4056-83f4-87d9ebdb3c68", "type": "concept", "title": "Data visualization, maps, timelines, comparison charts, and historiographical debates"}, {"id": "cee72d0c-d5e4-4fe0-9820-9fee043fa753", "type": "concept", "title": "Thesis, claims, counterevidence, Chicago-style citation, and revision"}], "description": "Students practice making evidence-based arguments across regions and time."}]}, {"id": "37e3235f-7134-4802-8421-a89a460b1c16", "type": "topic", "title": "Early Modern Transformations, Maritime Worlds, and the Columbian Exchange", "description": "This module traces the widening connections after 1400 through exploration, conquest, disease, crops, ecology, and the creation of new Atlantic, Pacific, and Indian Ocean systems.", "children": [{"id": "9966c0b5-2329-42d1-b0cd-a88913d1c28e", "type": "subtopic", "title": "Maritime exploration and encounter", "children": [{"id": "0b3466e3-d6ad-4e5d-9693-ecfbeb3c3422", "type": "concept", "title": "Portuguese, Spanish, Dutch, English, French, Chinese, Arab, Indian, and African maritime contexts"}, {"id": "306eb342-6d38-4ad9-bf56-a4ef5150bace", "type": "concept", "title": "Navigation, cartography, ships, ports, missionaries, merchants, pirates, and military technology"}, {"id": "16e8bf68-8fc1-48d7-ad22-4edce815cbef", "type": "concept", "title": "Encounter, conquest, diplomacy, trade, and Indigenous agency"}], "description": "Students study exploration as a global process shaped by state power, commerce, navigation, and violence."}, {"id": "314f3146-e36e-42c1-b4d2-a32d5ef3a023", "type": "subtopic", "title": "Columbian Exchange and ecological change", "children": [{"id": "c2320e2c-2e55-4a7b-926a-43ef79fa65ae", "type": "concept", "title": "Disease, crops, animals, weeds, microbes, foodways, demography, and environmental disruption"}, {"id": "ebbcb768-4524-43b3-b3a3-e330bcf5b24b", "type": "concept", "title": "Maize, potatoes, silver, sugar, horses, smallpox, and plantation ecologies"}, {"id": "5e50a127-11e9-440d-852d-b72ee7efb85f", "type": "concept", "title": "Unequal consequences for Indigenous peoples, Africans, Europeans, and Asian economies"}], "description": "The gist is to connect biology and environment to historical transformation."}, {"id": "5aac522c-edb5-422f-bdd9-7e034477f58c", "type": "subtopic", "title": "New global trade systems", "children": [{"id": "584db24d-7f71-424d-b1b7-2a2d4641cb15", "type": "concept", "title": "Atlantic, Pacific, Indian Ocean, Mediterranean, and overland networks"}, {"id": "1e8ef000-909f-4ce8-bf7f-d97b8186911c", "type": "concept", "title": "Silver flows, Manila galleons, spice trade, fur trade, textiles, porcelain, and credit"}, {"id": "fa745020-f3ad-4508-83ba-8a2d7c84a14a", "type": "concept", "title": "Merchant diasporas, chartered companies, piracy, smuggling, and state regulation"}], "description": "Students learn how early modern markets connected regions without making them equally powerful."}]}, {"id": "84e9d37f-e3bf-4486-bbd6-b268ee1a9ccb", "type": "topic", "title": "Early Modern Empires, Gunpowder States, and Cross-Cultural Governance", "description": "Students compare imperial power across Ottoman, Safavid, Mughal, Qing, Habsburg, Russian, and other state formations, asking how rulers governed diversity and mobilized resources.", "children": [{"id": "96ada875-3354-4cd6-ac8e-132aaf5b6b70", "type": "subtopic", "title": "Comparative imperial formations", "children": [{"id": "1883f0d6-4e17-447b-8006-8a494c5b7351", "type": "concept", "title": "Ottoman, Safavid, Mughal, Qing, Habsburg, Russian, Spanish, Portuguese, and Tokugawa systems"}, {"id": "9bc7f190-a094-4156-b3da-298eb12874ba", "type": "concept", "title": "Bureaucracy, military organization, taxation, law, dynastic legitimacy, court culture, and religion"}, {"id": "6242836d-e769-4d02-b2de-d95d1de57ff4", "type": "concept", "title": "Frontiers, provinces, tribute, local elites, ethnic diversity, and rebellion"}], "description": "Students compare how large states expanded and governed diverse populations."}, {"id": "ffb40858-2a74-4c56-8da5-dd3698a3a1c7", "type": "subtopic", "title": "Gunpowder and fiscal-military power", "children": [{"id": "fd62a7f8-4e8b-4b58-acbc-7c73338794f6", "type": "concept", "title": "Cannons, muskets, fortifications, navies, logistics, and military labor"}, {"id": "dc4b1adb-dc88-4942-9fb6-4051d13a3aec", "type": "concept", "title": "Taxation, land revenue, coinage, debt, monopolies, and administrative reform"}, {"id": "864c1984-ac06-4119-81d4-55613d1d354d", "type": "concept", "title": "Military revolution debates and limits of technology-centered explanation"}], "description": "The point is to connect military change to institutions and resources."}, {"id": "b87c65a9-d7b2-4755-a6e4-c66b552037eb", "type": "subtopic", "title": "Culture, religion, and governance", "children": [{"id": "9a29ab50-5908-40be-b4f1-0802b2e7537f", "type": "concept", "title": "Islamic law, Confucian bureaucracy, Catholic missions, Orthodox Christianity, Hindu kingship, and imperial rituals"}, {"id": "cc24d167-864b-4b3d-b97b-366266ffdd24", "type": "concept", "title": "Conversion, tolerance, persecution, syncretism, language, art, architecture, and education"}, {"id": "2a74c1c6-32cc-4bb0-a4d5-59377d91b9e6", "type": "concept", "title": "Imperial knowledge, mapping, censuses, ethnography, and classification"}], "description": "Students examine how imperial rule used culture as well as coercion."}]}, {"id": "f4095115-b984-40ad-bc31-8363d20162fd", "type": "topic", "title": "Atlantic Slavery, Plantation Economies, and Forced Migration", "description": "This topic centers slavery and forced migration as foundational to the modern world, connecting African, American, European, and Islamic-world histories.", "children": [{"id": "37b66d5e-fd16-4ca0-9ed9-2392d74900d6", "type": "subtopic", "title": "African societies and slave trades", "children": [{"id": "c8426aca-b7aa-4a43-846f-d9738330bdaa", "type": "concept", "title": "West, West Central, East, and interior African societies; Atlantic and Indian Ocean slave trades"}, {"id": "6a2086fb-977f-4773-88b3-789336fd1ad6", "type": "concept", "title": "War, captivity, commerce, states, kinship disruption, gender, and age"}, {"id": "e35946d4-6b09-49fc-be12-be3790bec824", "type": "concept", "title": "African agency, resistance, collaboration, and the danger of reducing African history to victimhood"}], "description": "Students place African history at the center of slavery's global development."}, {"id": "a5c6cd33-127e-4fe0-98c6-4f49c5f8678a", "type": "subtopic", "title": "Plantation economies and racial capitalism", "children": [{"id": "0db1b1b0-a8f3-4177-b6c6-d8f0c4c9d28e", "type": "concept", "title": "Sugar, tobacco, cotton, coffee, rice, mining, plantations, and port cities"}, {"id": "2c691c4c-62ba-4baf-a2b8-e4bd51d44fd2", "type": "concept", "title": "Labor regimes, surveillance, violence, law, finance, insurance, shipping, and consumer markets"}, {"id": "cea053a0-cd9b-4f43-a8f8-1ad14842ef7b", "type": "concept", "title": "Race-making, caste, freedom, manumission, reproduction, family, and community"}], "description": "The gist is to understand slavery as an economic, legal, racial, and ecological system."}, {"id": "8e455a82-95f5-41b1-8ba5-67306d025b16", "type": "subtopic", "title": "Resistance, abolition, and memory", "children": [{"id": "3eca4c38-cba7-470f-9da8-734ed9cc3902", "type": "concept", "title": "Maroons, rebellions, everyday resistance, cultural survival, religion, music, language, and family strategies"}, {"id": "b16ecf1b-810c-43cc-82f8-58a54dd0c8fb", "type": "concept", "title": "Abolition movements, Haitian Revolution, British abolition, gradual emancipation, and illegal trade"}, {"id": "48f004bd-b17a-4710-be10-dab727971744", "type": "concept", "title": "Memory, reparations, museums, monuments, archives, and data ethics"}], "description": "Students examine enslaved people and abolitionists as makers of history."}]}, {"id": "032f0f2d-3e43-41ad-96aa-68b754471751", "type": "topic", "title": "Science, Enlightenment, Religious Change, and Knowledge Networks", "description": "Students examine how scientific inquiry, print, religion, reform, empire, and Enlightenment thought transformed authority, knowledge, and political imagination.", "children": [{"id": "e869f85d-c403-4da8-916c-0441421223eb", "type": "subtopic", "title": "Scientific Revolution and knowledge circulation", "children": [{"id": "8519fa86-8954-4492-a2f4-7bb9ea298132", "type": "concept", "title": "Astronomy, anatomy, mechanics, botany, medicine, navigation, measurement, and experiment"}, {"id": "00bd5a31-7495-47b0-9e38-8a1a81d1ccc0", "type": "concept", "title": "Universities, academies, print, correspondence, instruments, translation, and colonial collecting"}, {"id": "63f226a7-5f4b-488d-941a-4d19753a853c", "type": "concept", "title": "Knowledge from Indigenous, Islamic, Chinese, South Asian, African, and European traditions"}], "description": "Students study science as a social and global process, not just a list of discoveries."}, {"id": "49206689-22ee-4a2f-9148-f28766a66d9b", "type": "subtopic", "title": "Enlightenment and public spheres", "children": [{"id": "0582c4f9-65f0-40b8-a799-b5b71f65fcc7", "type": "concept", "title": "Reason, natural rights, sovereignty, progress, political economy, toleration, and critique"}, {"id": "ae245e10-31e3-4d6a-ba0b-5e0e4a43274f", "type": "concept", "title": "Salons, coffeehouses, pamphlets, newspapers, encyclopedias, censorship, and literacy"}, {"id": "f02fbc59-0585-48ac-8b8d-868abf0e0c67", "type": "concept", "title": "Contradictions around slavery, empire, gender, race, and property"}], "description": "The point is to see political ideas moving through institutions, media, and debate."}, {"id": "ad0c8fd6-53b3-4211-8f43-124272d5f61c", "type": "subtopic", "title": "Religious reform and conflict", "children": [{"id": "95749fd0-fcd5-4387-9fca-4003cf3cb1f4", "type": "concept", "title": "Reformation legacies, Catholic reform, Islamic reform, revival movements, missions, secularism, and syncretism"}, {"id": "f5699f07-b13c-4763-a2a2-bb11f1543f63", "type": "concept", "title": "Confessional states, religious minorities, conversion, education, law, and family life"}, {"id": "1c647f56-64a5-40cd-bb2a-c743c7ed1335", "type": "concept", "title": "Religion as both authority and critique in modern politics"}], "description": "Students connect religious change to state power, identity, and social life."}]}, {"id": "dee2bace-53c5-4d12-be6e-28f3d2b93495", "type": "topic", "title": "Atlantic Revolutions: American, French, Haitian, and Latin American Transformations", "description": "This module studies revolution as a connected Atlantic process involving rights, slavery, citizenship, violence, race, class, gender, and new states.", "children": [{"id": "035c9467-8e4e-4aa1-b5df-cfa0fc2881da", "type": "subtopic", "title": "Revolutionary ideas and institutions", "children": [{"id": "8385f013-d69a-43d9-8094-5ea2573c8f95", "type": "concept", "title": "Republicanism, liberalism, citizenship, constitutions, representation, and natural rights"}, {"id": "16020cba-7afd-4795-9b5b-db38380ddd2a", "type": "concept", "title": "Fiscal crisis, war, colonial grievance, print culture, and political mobilization"}, {"id": "8055a70a-91d0-492b-ad37-07ff1018ac3e", "type": "concept", "title": "Limits of equality by race, gender, class, property, and colonial status"}], "description": "Students learn how ideas of rights and sovereignty became political programs."}, {"id": "b103537a-5dcc-423a-b99d-d7b24895df9f", "type": "subtopic", "title": "Haiti and slavery in the age of revolution", "children": [{"id": "9d0e5ed7-7c00-4d4f-b671-10a06bf7b78c", "type": "concept", "title": "Saint-Domingue, plantation slavery, free people of color, enslaved insurgency, Toussaint Louverture, and independence"}, {"id": "a69eb1a2-c099-40ad-a704-8968f100ab0a", "type": "concept", "title": "Race, abolition, empire, military struggle, diplomacy, and economic isolation"}, {"id": "147b88a7-d94c-46c2-b610-fc90eaba8d30", "type": "concept", "title": "Haiti's influence on abolition, Latin America, U.S. politics, and imperial fear"}], "description": "The gist is to center the Haitian Revolution as a decisive world-historical event."}, {"id": "594fa21c-25e9-42a7-886c-1da1db02b59e", "type": "subtopic", "title": "Latin American independence and new states", "children": [{"id": "652ef4db-f9bc-4292-a714-eb8c997cd5b9", "type": "concept", "title": "Spanish and Portuguese empires, creole elites, Indigenous communities, enslaved peoples, and mixed-race populations"}, {"id": "245f7171-548b-44a5-8d0a-a9508ff79a66", "type": "concept", "title": "Bolivar, San Martin, Hidalgo, Morelos, Brazil, Mexico, Gran Colombia, and the Caribbean"}, {"id": "e9501c91-74ac-400d-8bb2-5774169f306b", "type": "concept", "title": "Nation formation, caudillos, constitutions, citizenship, land, and inequality"}], "description": "Students connect independence to social conflict and state-building."}]}, {"id": "21513da7-0fc2-4a49-9f44-0f14dcd06990", "type": "topic", "title": "Industrial Revolution, Capitalism, Labor, and Urbanization", "description": "Students analyze industrialization as a global transformation in energy, labor, production, finance, environment, and everyday life.", "children": [{"id": "0af81a24-e9de-4c8b-9163-39f250ee3f60", "type": "subtopic", "title": "Industrialization and energy", "children": [{"id": "6c1f012e-2a91-4cb1-b255-ee56dd7dc091", "type": "concept", "title": "Coal, steam, factories, mechanized textiles, railroads, steel, electricity, and fossil fuels"}, {"id": "17e50d35-7e2c-4e17-b062-4e6587fdae33", "type": "concept", "title": "Britain, continental Europe, North America, Japan, Russia, India, China, and global unevenness"}, {"id": "1f74e026-4f22-4345-89da-833e414395d5", "type": "concept", "title": "Energy transitions, pollution, resource extraction, and climate history"}], "description": "Students learn why industrialization transformed production, environment, and global power."}, {"id": "a82eb51f-3722-4ca6-a48f-62d2dfda41f0", "type": "subtopic", "title": "Capitalism, finance, and global markets", "children": [{"id": "82a27e31-77ac-425a-a7bb-f5065befc001", "type": "concept", "title": "Banks, joint-stock companies, insurance, commodities, consumer goods, tariffs, and free trade"}, {"id": "6cf62979-5382-484c-ad50-9e91b3996f83", "type": "concept", "title": "Cotton, sugar, opium, rubber, tea, oil, and global supply chains"}, {"id": "fabcc3f8-24d7-4359-90d3-48ac2b0863d4", "type": "concept", "title": "Booms, crashes, inequality, dependency, and critiques of capitalism"}], "description": "The point is to connect factories to credit, empire, trade, and households."}, {"id": "3e71e086-8ad4-459d-abf6-0f3277a45160", "type": "subtopic", "title": "Workers, cities, and social change", "children": [{"id": "030bc8c5-7d1d-41d9-9a32-88d54b91e8d4", "type": "concept", "title": "Factory labor, wage work, child labor, unions, strikes, migration, and class formation"}, {"id": "3e1ffac3-7058-4521-95c0-dc4faf828b4a", "type": "concept", "title": "Urbanization, sanitation, housing, public health, policing, education, and leisure"}, {"id": "7bad8130-6ace-42ab-87c6-034a44cc5ce4", "type": "concept", "title": "Gender, family economies, domestic labor, and reform movements"}], "description": "Students examine industrial modernity from below."}]}, {"id": "f2b0811c-9cf5-44eb-ace3-bbd596cfa247", "type": "topic", "title": "Nationalism, Liberalism, Socialism, and Nineteenth-Century State-Building", "description": "This topic explains how modern ideologies and state projects remade political identities, law, citizenship, welfare, class politics, and social movements.", "children": [{"id": "905977b1-db20-4871-8eb6-cf9e0892fd7e", "type": "subtopic", "title": "Nationalism and political identity", "children": [{"id": "dd785247-453f-4bdb-9da7-a71a29f8a9e5", "type": "concept", "title": "Language, schools, armies, maps, print, census, folklore, monuments, and public rituals"}, {"id": "79fb8ba6-ae15-4d66-be6d-18fc3d88eb47", "type": "concept", "title": "Unification, separatism, empire, minorities, citizenship, and exclusion"}, {"id": "10dbaf12-77fa-40c9-b0c5-0f39207153ca", "type": "concept", "title": "Germany, Italy, Balkans, Ottoman reform, Japan, Latin America, and anti-colonial nationalism"}], "description": "Students study nations as historical creations rather than timeless facts."}, {"id": "4907c5f1-f54d-486b-8468-ccd02516c36d", "type": "subtopic", "title": "Liberalism, conservatism, socialism, and reform", "children": [{"id": "f82d09bd-74de-488d-b09c-ab20f3ffc57a", "type": "concept", "title": "Rights, constitutions, markets, property, order, class, revolution, and welfare"}, {"id": "f66df505-cf1b-476b-b32c-e7cd4fb5a299", "type": "concept", "title": "Marxism, anarchism, labor parties, trade unions, cooperatives, and social democracy"}, {"id": "eb1e1b06-b235-4647-8ade-7c57bfa7b357", "type": "concept", "title": "Women, suffrage, education, abolition, temperance, public health, and reform politics"}], "description": "The gist is to connect ideology to institutions and social conflict."}, {"id": "c8560152-7b71-44da-a93f-5bef1a3283b9", "type": "subtopic", "title": "Modern state capacity", "children": [{"id": "35b011ff-8d2e-44a5-bff7-676e56d4907a", "type": "concept", "title": "Bureaucracy, census, passports, schools, conscription, police, courts, welfare, and infrastructure"}, {"id": "e1c8a098-a719-4ab8-be11-7412e15913ff", "type": "concept", "title": "Taxation, debt, public health, urban planning, statistics, and colonial administration"}, {"id": "239ed77d-0842-48f0-abf9-b2770d920b31", "type": "concept", "title": "Citizenship, surveillance, rights, obligations, and resistance"}], "description": "Students analyze how states became more intrusive and more service-providing."}]}, {"id": "460f84aa-e7c3-4229-b05e-dd894f4e44ff", "type": "topic", "title": "High Imperialism, Colonial Rule, and Anti-Colonial Resistance", "description": "Students examine formal and informal empire, colonial knowledge, racial hierarchy, extraction, collaboration, resistance, and the global consequences of imperial rule.", "children": [{"id": "814beca4-11c6-4d03-b42d-78fb6bc91fcb", "type": "subtopic", "title": "Imperial expansion and colonial rule", "children": [{"id": "6e3ea83a-d9ba-4d49-b40b-039a98585104", "type": "concept", "title": "Scramble for Africa, British India, French empire, Dutch East Indies, Russian expansion, U.S. empire, and Japanese empire"}, {"id": "a8259c06-b65d-49a5-828d-f4df44079395", "type": "concept", "title": "Conquest, treaties, settler colonialism, indirect rule, extraction, missions, and infrastructure"}, {"id": "7eaf889c-b393-4ac7-a7fa-bfd0ed5eed32", "type": "concept", "title": "Racial ideology, social Darwinism, Orientalism, civilizing missions, and colonial law"}], "description": "Students examine why empire intensified in the nineteenth century and how it operated."}, {"id": "84fa54b6-8833-4bc7-8d32-7e558bc3fff4", "type": "subtopic", "title": "Colonial knowledge and economies", "children": [{"id": "66f36dfb-2296-4aaf-9fc7-2ae7c65d6b18", "type": "concept", "title": "Censuses, ethnography, maps, museums, schools, medical campaigns, and legal codes"}, {"id": "f8503518-001a-4eca-ac01-7c53893a7150", "type": "concept", "title": "Cash crops, mines, plantations, railways, taxes, forced labor, and land alienation"}, {"id": "f48be68f-7e47-4059-ba3b-5481e7192ff0", "type": "concept", "title": "Ecological change, famine, disease, conservation, and resource extraction"}], "description": "The point is to see how empire classified people and reorganized labor, land, and nature."}, {"id": "e530aed6-19f2-4709-89d4-7abe23f94dc5", "type": "subtopic", "title": "Resistance and anti-colonial politics", "children": [{"id": "1156dc8e-3834-40aa-b9f3-f8707fba8edf", "type": "concept", "title": "Rebellions, petitions, religious movements, labor strikes, intellectual critique, and nationalist parties"}, {"id": "ebc2ff9d-221e-485b-b893-3abc1b9121f7", "type": "concept", "title": "India, Africa, Southeast Asia, Middle East, Caribbean, Pacific, and Indigenous movements"}, {"id": "2cdf5d22-7379-40ee-b0ae-f1ed21939038", "type": "concept", "title": "Collaboration, accommodation, elite politics, peasant politics, and women in resistance"}], "description": "Students learn that empire was continually contested."}]}, {"id": "f1b26b29-9583-463a-9fef-55ca2ef8368a", "type": "topic", "title": "Global Migration, Diaspora, Gender, and Everyday Life in the Modern World", "description": "This module follows migrants, workers, families, women, and communities across empires and nation-states to show how modernity was lived from below.", "children": [{"id": "79d922a7-24d7-4e15-93d7-0887593fb99d", "type": "subtopic", "title": "Migration and diaspora", "children": [{"id": "e0d6e51d-ba9e-42da-a355-7ff6bd2f1373", "type": "concept", "title": "Indentured labor, settler migration, refugees, rural-urban migration, labor migration, and exile"}, {"id": "d74c7c8d-5f10-4882-a965-dd88c773172e", "type": "concept", "title": "Chinese, Indian, African, Caribbean, Irish, Italian, Jewish, Arab, Japanese, and other diasporas"}, {"id": "97ef6047-aac5-43b4-ab70-13e5793e24ce", "type": "concept", "title": "Citizenship, borders, passports, remittances, racial exclusion, and migrant networks"}], "description": "Students follow mobility as a central feature of modern history."}, {"id": "a3bc286c-e88f-4f7c-a4ba-a33950e46b05", "type": "subtopic", "title": "Gender, family, and social reform", "children": [{"id": "70341af5-47ac-4f9f-adc1-f1ccf1d2b77f", "type": "concept", "title": "Marriage, reproduction, education, property rights, suffrage, sexuality, motherhood, and care work"}, {"id": "7af45213-a518-468c-81c7-90ababc3cea4", "type": "concept", "title": "Feminist movements, social purity, abolition, labor activism, and anti-colonial women's politics"}, {"id": "dfeb4056-31af-4b44-a955-12e60b5c70cf", "type": "concept", "title": "Masculinity, military service, domesticity, and changing family economies"}], "description": "The gist is to see modern transformation inside households and social institutions."}, {"id": "a510ac8a-0ae2-43f8-b090-286b8559a730", "type": "subtopic", "title": "Everyday life and culture", "children": [{"id": "5f9eed26-7bce-47ec-8096-3c66c491aa01", "type": "concept", "title": "Consumer culture, newspapers, cinema, sport, religion, schools, public health, and popular politics"}, {"id": "1351a286-0dd9-49e1-b1e3-107e8351e223", "type": "concept", "title": "Urban neighborhoods, rural communities, workplaces, markets, and domestic spaces"}, {"id": "0bfe6b5b-ad16-4002-8ee2-110d33de581e", "type": "concept", "title": "Microhistory, oral history, photographs, memoirs, and local archives"}], "description": "Students connect large processes to food, housing, media, leisure, and belief."}]}, {"id": "a4794274-11f0-4543-880b-35ab319e2f16", "type": "topic", "title": "World War I, Total War, Empire, and Revolution", "description": "Students learn how the First World War reshaped empires, societies, labor, gender, nationalism, revolution, diplomacy, and mass violence.", "children": [{"id": "f67a7114-d4d6-43a6-bf29-44bde49d35cb", "type": "subtopic", "title": "Causes and global scope", "children": [{"id": "7c10be1a-730b-428d-811b-32648a1e15b4", "type": "concept", "title": "Alliance systems, imperial rivalry, nationalism, militarism, crises, and assassination"}, {"id": "133efca6-7efe-415e-b744-d7a648f4f4c5", "type": "concept", "title": "Colonial troops, laborers, Middle East, Africa, Asia, Pacific, and global logistics"}, {"id": "67becdb0-117a-411f-b38b-65b3b47dc4f2", "type": "concept", "title": "Home fronts, propaganda, censorship, rationing, and total-war economies"}], "description": "Students move beyond a Europe-only explanation of World War I."}, {"id": "a9c1db83-46e8-4657-9c41-65056d6015a8", "type": "subtopic", "title": "War experience and social transformation", "children": [{"id": "4ebd55e6-a09e-48d3-9f6c-8ec56ae9fc2a", "type": "concept", "title": "Trench warfare, technology, casualties, trauma, medicine, prisoners, occupation, and displacement"}, {"id": "d9278ba8-a9b8-441c-aa7b-654475ad172d", "type": "concept", "title": "Women workers, labor conflict, minority populations, race, empire, and veterans"}, {"id": "f1dd211f-ebda-4ef7-9da4-936007ae4b54", "type": "concept", "title": "Memory, mourning, monuments, literature, and war culture"}], "description": "The point is to understand how mass war transformed societies."}, {"id": "210fdeac-7874-40a1-b1f9-cb9ed9b99f00", "type": "subtopic", "title": "Revolution and postwar settlement", "children": [{"id": "40a3995b-40d0-479d-8039-8ac502a41c71", "type": "concept", "title": "Russian Revolution, Ottoman collapse, Habsburg collapse, German revolution, and colonial unrest"}, {"id": "cb6919dd-baa9-43d1-bd1c-18d95eafb608", "type": "concept", "title": "Treaty of Versailles, League of Nations, mandates, self-determination, and reparations"}, {"id": "df511a3f-37ca-42d9-b49b-704b937e2593", "type": "concept", "title": "Armenian genocide, border-making, refugee crises, and unresolved conflicts"}], "description": "Students examine the war's political consequences."}]}, {"id": "0441e06f-2d1b-4fce-ae47-3a7ed3834e07", "type": "topic", "title": "Interwar Crisis, Fascism, Depression, and World War II", "description": "This topic links economic crisis, authoritarianism, ideology, genocide, resistance, total war, and the remaking of international order.", "children": [{"id": "b397bdf3-1deb-484f-82b5-2357c1d0b11f", "type": "subtopic", "title": "Interwar instability", "children": [{"id": "765b53a0-66ad-43c0-87aa-41a0ee9a623a", "type": "concept", "title": "Great Depression, inflation, unemployment, debt, protectionism, and global trade collapse"}, {"id": "7bc576bb-6cd7-4f45-8615-e9395716fef0", "type": "concept", "title": "Democracy, authoritarianism, fascism, communism, military regimes, and populism"}, {"id": "139b6c27-b860-4bfb-bf93-22ec90022158", "type": "concept", "title": "Japan, Germany, Italy, Spain, Soviet Union, China, Latin America, and colonial worlds"}], "description": "Students connect economic crisis to political radicalization and state failure."}, {"id": "2a0cdbe3-a5c0-4cd3-b508-7c07caef184f", "type": "subtopic", "title": "World War II and genocide", "children": [{"id": "8a1339db-8d0b-49fb-922c-c09a257273f0", "type": "concept", "title": "Axis expansion, Allied coalition, Pacific War, Eastern Front, bombing, occupation, collaboration, and resistance"}, {"id": "b8566fa8-f135-4563-aaaf-a6e398b5f6d6", "type": "concept", "title": "Holocaust, genocide, racial war, forced labor, medical crimes, and civilian targeting"}, {"id": "3dac1349-dd12-4985-9b7c-b16a681ccae5", "type": "concept", "title": "Atomic bombings, strategic bombing, famine, displacement, and moral debate"}], "description": "The gist is to study total war alongside ideology, occupation, and mass murder."}, {"id": "e448bbe1-2f73-462e-b484-b3b5748d4e91", "type": "subtopic", "title": "War outcomes and memory", "children": [{"id": "9d45386a-0dfa-41b3-8c14-81c12650c8d4", "type": "concept", "title": "United Nations, Bretton Woods, war crimes trials, occupation, reconstruction, and partition"}, {"id": "ecfa060d-0987-474e-bac8-e9dc8dd86e7a", "type": "concept", "title": "Cold War origins, decolonization pressures, human rights language, and refugee regimes"}, {"id": "07fec23a-3229-4be0-90ff-2cb050d05d6b", "type": "concept", "title": "Museums, memorials, testimony, denial, commemoration, and historical responsibility"}], "description": "Students analyze how World War II remade global order and public memory."}]}, {"id": "3827ba79-9561-4065-b9b7-2929be6da427", "type": "topic", "title": "Cold War, Decolonization, Development, and Non-Aligned Worlds", "description": "Students study the post-1945 world through superpower rivalry, decolonization, revolutionary movements, development projects, apartheid, and non-aligned politics.", "children": [{"id": "3e5095e5-2a6b-4677-b682-cefad74f1c82", "type": "subtopic", "title": "Cold War systems", "children": [{"id": "81d9a99c-b9cc-4dd1-93a1-fd048d86ab14", "type": "concept", "title": "NATO, Warsaw Pact, nuclear arms, espionage, propaganda, space race, and ideological competition"}, {"id": "fc1e3508-d346-449b-9069-39b4d7b1d14c", "type": "concept", "title": "Korea, Vietnam, Cuba, Afghanistan, Latin America, Africa, Middle East, and Asia"}, {"id": "faa69b05-4e86-443d-9cf3-31464a76e7a1", "type": "concept", "title": "Proxy wars, coups, covert action, peace movements, and nuclear fear"}], "description": "Students study the Cold War as a global conflict, not only U.S.-Soviet rivalry."}, {"id": "c4b75b61-2738-44a4-99c7-f59f732625e1", "type": "subtopic", "title": "Decolonization and new nations", "children": [{"id": "524f5339-efdd-4fc6-81db-983b164418bc", "type": "concept", "title": "India/Pakistan, Indonesia, Ghana, Algeria, Kenya, Vietnam, Egypt, Caribbean, and Pacific decolonization"}, {"id": "221f2cab-ae26-438c-8d70-0c53008d2f17", "type": "concept", "title": "Nationalist parties, armed struggle, negotiation, partition, refugees, citizenship, and borders"}, {"id": "90d70907-9566-4e3e-8d1f-012125340ae3", "type": "concept", "title": "Non-Aligned Movement, Bandung, Pan-Africanism, Arab nationalism, and Third World politics"}], "description": "The point is to connect independence struggles to state-building and global politics."}, {"id": "9523c481-8cba-4a3c-9794-9068774c0c16", "type": "subtopic", "title": "Development and postcolonial challenges", "children": [{"id": "98420622-455a-4ae8-82be-c28805e5422c", "type": "concept", "title": "Modernization, dependency, socialism, land reform, industrial policy, aid, debt, and institutions"}, {"id": "0940f00c-cfae-42bd-8d79-6104a1f8e818", "type": "concept", "title": "Apartheid, civil wars, authoritarianism, democracy, oil, agriculture, famine, and public health"}, {"id": "2d1e490b-c192-467a-ad33-b57a0309f880", "type": "concept", "title": "Gender, education, migration, NGOs, and critiques of development"}], "description": "Students examine promises and contradictions of development."}]}, {"id": "fd9e96d3-a4da-451c-9ef5-4dfd2830fa6e", "type": "topic", "title": "Globalization, Human Rights, Environment, and Contemporary World Orders", "description": "This module connects late twentieth- and twenty-first-century history to trade, technology, migration, rights, inequality, climate, public health, and memory.", "children": [{"id": "79cc305f-7c41-417a-bfe6-563600a95b42", "type": "subtopic", "title": "Late twentieth-century globalization", "children": [{"id": "e9c99431-e16c-4d90-b004-d59e14f5ad42", "type": "concept", "title": "Trade liberalization, containers, finance, outsourcing, information technology, and supply chains"}, {"id": "3ff3c94a-7843-40fc-8ca5-202bf6aa1ce3", "type": "concept", "title": "Neoliberalism, debt crises, structural adjustment, regional blocs, and multinational corporations"}, {"id": "40a51825-5b0a-4cf4-b1af-0a964aa75780", "type": "concept", "title": "China's reforms, European integration, migration, inequality, and labor precarity"}], "description": "Students trace the historical roots of current interconnected systems."}, {"id": "2afd4760-5204-4e7c-944f-525d741afb57", "type": "subtopic", "title": "Human rights and social movements", "children": [{"id": "96546e11-d4f5-422a-a3ed-6642f8474bc4", "type": "concept", "title": "Universal Declaration of Human Rights, civil rights, feminism, Indigenous rights, LGBTQ movements, disability rights, and transitional justice"}, {"id": "7c0fc29e-07b7-4040-a6e7-08fde72e2e73", "type": "concept", "title": "NGOs, courts, truth commissions, humanitarianism, refugees, and international law"}, {"id": "8e58d45f-fd60-43aa-b6f3-c700062af652", "type": "concept", "title": "Tensions between sovereignty, intervention, security, and rights claims"}], "description": "The gist is to understand rights as historically constructed and politically contested."}, {"id": "b94e803e-19e0-4df7-907c-f6905ce1efc6", "type": "subtopic", "title": "Environment, health, and memory", "children": [{"id": "fdf00b6e-13cb-468c-9a2f-1e7a120207d7", "type": "concept", "title": "Climate change, fossil fuels, conservation, pollution, pandemics, food systems, and urban vulnerability"}, {"id": "3b6bbb41-e110-4de8-bf8b-96ee0ad21d2d", "type": "concept", "title": "Public health, HIV/AIDS, COVID-era historical parallels, population, and global inequality"}, {"id": "23926da4-e1a4-4529-8856-a099b873bbcb", "type": "concept", "title": "Public memory, monuments, museums, reparations, historical denial, and digital misinformation"}], "description": "Students connect contemporary crises to long-term historical processes."}]}, {"id": "b0d421ef-320b-4ae5-89d5-b3cdd7d35da7", "type": "topic", "title": "Research Capstone: Modern World History Evidence, Historiography, and Public Memory", "description": "Students synthesize the course through a source-based project that makes a historical argument for a real audience.", "children": [{"id": "d4d56b6d-ae3a-4b94-a715-746bdfe20aa8", "type": "subtopic", "title": "Research question and scope", "children": [{"id": "58ca9c8f-e104-4ced-acf6-5d67ece409a8", "type": "concept", "title": "Topic selection, region, chronology, scale, comparison, connection, and research question"}, {"id": "0e22d19e-5ef0-454b-876b-5b8db54516f7", "type": "concept", "title": "Primary-source corpus, secondary scholarship, historiography, and annotated bibliography"}, {"id": "029284d1-4b81-4ffd-93dd-a62c99f1f8a0", "type": "concept", "title": "Archive plan, data/source log, citation workflow, and revision schedule"}], "description": "Students turn a large modern-world issue into a feasible historical project."}, {"id": "5a7d1028-3a12-43f3-906c-c31dc49d477b", "type": "subtopic", "title": "Evidence and interpretation", "children": [{"id": "25afe760-4b9b-4e12-b29a-cb0ed7a77909", "type": "concept", "title": "Close reading, corroboration, contextualization, contradiction, and source limitations"}, {"id": "20df1ae8-48ea-4c3e-b05a-e2fb3689e8f8", "type": "concept", "title": "Documents, oral histories, photographs, maps, objects, newspapers, data, and audiovisual sources"}, {"id": "2e5f299a-e3cf-4bd3-86f0-3b6480c8209e", "type": "concept", "title": "Translation, ethics, representation, archival silence, and responsible uncertainty"}], "description": "The point is to build an argument from sources rather than assemble facts."}, {"id": "4f1afcec-b582-4506-b56a-530c9cc1384a", "type": "subtopic", "title": "Public history communication", "children": [{"id": "584dc659-63fd-401e-aa26-47b3355575a2", "type": "concept", "title": "Research essay, digital exhibit, podcast script, map story, museum label set, or presentation"}, {"id": "1f10e225-a90e-484a-93fd-0740d09c04de", "type": "concept", "title": "Thesis, narrative structure, visual evidence, accessibility, captions, and source transparency"}, {"id": "459a8b0c-2a73-4c20-9ea2-84b8200001b5", "type": "concept", "title": "Reflection on memory, audience, present-day relevance, and limits of the project"}], "description": "Students practice explaining modern world history clearly to an audience."}]}], "dbBacked": true}$wh2json$::jsonb,
